const shouldInterjectSpec = async () => {
  const timeSinceLastSpeech = Date.now() - lastSpeechTime;
  const specIncomplete = !currentSpec.what || !currentSpec.why;

  // Check uncertainty markers in recent transcript
  const recentText = transcriptHistory.slice(-5).map(t => t.text).join(' ');
  const hasUncertainty = /\b(um|uh|maybe|I think|not sure|probably)\b/i.test(recentText);

  // Check training data to predict if this is good timing
  const trainingRecords = await runtime.call('graph-db.getNodesByType', 'spec-training');
  if (trainingRecords.length >= config.minTrainingRecords) {
    const prediction = predictInterjectionSuccess(trainingRecords, {
      timeSinceLastSpeech,
      hasUncertainty,
      specIncomplete
    });
    return prediction.shouldInterject;
  }

  // Fallback: always interject if incomplete or long pause
  return specIncomplete || hasUncertainty || timeSinceLastSpeech > 60000;
};

const predictInterjectionSuccess = (records, currentContext) => {
  // Simple pattern matching from training data
  const similar = records.filter(r => {
    const pauseSimilar = Math.abs(r.context.pauseDuration - currentContext.timeSinceLastSpeech) < 10000;
    const uncertaintySimilar = 
      (currentContext.hasUncertainty && /\b(um|uh|maybe)\b/i.test(r.context.recentTranscript)) ||
      (!currentContext.hasUncertainty && !/\b(um|uh|maybe)\b/i.test(r.context.recentTranscript));
    return pauseSimilar && uncertaintySimilar;
  });

  if (similar.length < 5) return { shouldInterject: true, confidence: 0.5 };

  const successRate = similar.filter(r => 
    r.userFeedback.action === 'accepted' || r.userFeedback.rightTiming === true
  ).length / similar.length;

  return { 
    shouldInterject: successRate > 0.6, 
    confidence: successRate 
  };
};

